function f = HS49_f(x)
f = (x(1) - x(2)).^2 + (x(3) - 1).^2 + (x(4) - 1).^4 + (x(5) - 1).^6;
end

function g = HS49_g(x)
g = zeros(5, 1);
g(1) = 2*x(1) - 2*x(2);
g(2) = -2*x(1) + 2*x(2);
g(3) = 2*x(3) - 2;
g(4) = 4*(x(4) - 1).^3;
g(5) = 6*(x(5) - 1).^5;
end

function c = HS49_c(x)
c = zeros(2, 1);
c(1) = x(1) + x(2) + x(3) + 4*x(4) - 7;
c(2) = x(3) + 5*x(5) - 6;
end

